18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	
46	const SWORD_BASE_PREMIUM = 100;
47	const AMULET_BASE_PREMIUM = 60;
48	
49	/** Percentages are applied as integer arithmetic so that the final
50	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
51	const addPercent = (amount: number, percent: number): number =>
52	  amount + (amount * percent) / 100;
53	
54	/** Rounds up — premiums round in the MHPCO's favour. */
55	const roundPremium = (amount: number): number => Math.ceil(amount);
56	
57	const itemBasePremium = (item: Item): number =>
58	  item.type === "amulet" ? AMULET_BASE_PREMIUM : SWORD_BASE_PREMIUM;
59	
60	const policyBasePremium = (items: Item[]): number =>
61	  items.reduce((total, item) => total + itemBasePremium(item), 0);
62	
63	const quote = (step: QuoteStep): StepResult => {
64	  const basePremium = policyBasePremium(step.items);
65	  const premium =
66	    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
67	  return { premium: roundPremium(premium) };
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => {
71	  const results = scenario.steps.map((step) => quote(step as QuoteStep));
72	  return { results };
73	};
